// src/components/Modal.js
// Modern Modal Component

import React, { useState, useEffect } from 'react';
import { X, Plus, Zap, FolderPlus } from 'lucide-react';
import { validateIdea, validateTask, ToastManager, formatCharCount } from '../utils/validation';

// Ana Modal Container
export const Modal = ({ isOpen, onClose, children, title, maxWidth = '500px' }) => {
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div 
        className="modal-container" 
        style={{ maxWidth }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-header">
          <h2 className="modal-title">{title}</h2>
          <button className="modal-close" onClick={onClose}>
            <X size={20} />
          </button>
        </div>
        <div className="modal-body">
          {children}
        </div>
      </div>
    </div>
  );
};

// Alt Fikir Ekleme Modal'ı
export const AddSubIdeaModal = ({ isOpen, onClose, onSubmit, parentTitle }) => {
  const [formData, setFormData] = useState({
    title: '',
    description: ''
  });
  const [errors, setErrors] = useState({});

  const handleSubmit = (e) => {
    e.preventDefault();
    
    const validation = validateIdea(formData);
    if (!validation.isValid) {
      setErrors(validation.errors);
      ToastManager.show('Lütfen form hatalarını düzeltin', 'error');
      return;
    }

    onSubmit(formData.title.trim(), formData.description.trim());
    setFormData({ title: '', description: '' });
    setErrors({});
    onClose();
  };

  const handleClose = () => {
    setFormData({ title: '', description: '' });
    setErrors({});
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Alt Fikir Ekle" maxWidth="600px">
      <div className="modal-info">
        <p><strong>Ana Fikir:</strong> {parentTitle}</p>
      </div>
      
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Alt Fikir Başlığı *</label>
          <input
            type="text"
            value={formData.title}
            onChange={(e) => {
              setFormData(prev => ({ ...prev, title: e.target.value }));
              if (errors.title) {
                setErrors(prev => ({ ...prev, title: null }));
              }
            }}
            className={`form-input ${errors.title ? 'error' : ''}`}
            placeholder="Alt fikrinizin başlığını yazın..."
            autoFocus
          />
          {errors.title && <div className="error-message">{errors.title}</div>}
          <div className="char-count">{formatCharCount(formData.title.length, 100).text}</div>
        </div>

        <div className="form-group">
          <label>Açıklama</label>
          <textarea
            value={formData.description}
            onChange={(e) => {
              setFormData(prev => ({ ...prev, description: e.target.value }));
              if (errors.description) {
                setErrors(prev => ({ ...prev, description: null }));
              }
            }}
            className={`form-textarea ${errors.description ? 'error' : ''}`}
            placeholder="Alt fikrinizi detaylı olarak açıklayın..."
            rows={3}
          />
          {errors.description && <div className="error-message">{errors.description}</div>}
          <div className="char-count">{formatCharCount(formData.description.length, 500).text}</div>
        </div>

        <div className="modal-actions">
          <button type="button" onClick={handleClose} className="btn btn-secondary">
            İptal
          </button>
          <button type="submit" className="btn btn-primary">
            <FolderPlus size={16} />
            Alt Fikir Ekle
          </button>
        </div>
      </form>
    </Modal>
  );
};

// Export/Import Modal'ı
export const ExportImportModal = ({ isOpen, onClose, onExport, onImport, stats }) => {
  const [activeTab, setActiveTab] = useState('export');
  const [importFile, setImportFile] = useState(null);
  const [importing, setImporting] = useState(false);

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file && file.type === 'application/json') {
      setImportFile(file);
    } else {
      ToastManager.show('Lütfen geçerli bir JSON dosyası seçin', 'error');
    }
  };

  const handleImport = async () => {
    if (!importFile) {
      ToastManager.show('Lütfen bir dosya seçin', 'error');
      return;
    }

    setImporting(true);
    try {
      await onImport(importFile);
      setImportFile(null);
      onClose();
    } catch (error) {
      console.error('Import error:', error);
    } finally {
      setImporting(false);
    }
  };

  const handleClose = () => {
    setImportFile(null);
    setActiveTab('export');
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Veri Yönetimi" maxWidth="700px">
      <div className="export-import-tabs">
        <button 
          className={`tab-btn ${activeTab === 'export' ? 'active' : ''}`}
          onClick={() => setActiveTab('export')}
        >
          📤 Export
        </button>
        <button 
          className={`tab-btn ${activeTab === 'import' ? 'active' : ''}`}
          onClick={() => setActiveTab('import')}
        >
          📥 Import
        </button>
        <button 
          className={`tab-btn ${activeTab === 'stats' ? 'active' : ''}`}
          onClick={() => setActiveTab('stats')}
        >
          📊 İstatistikler
        </button>
      </div>

      {activeTab === 'export' && (
        <div className="tab-content">
          <h4>Verilerinizi Yedekleyin</h4>
          <p className="tab-description">
            Tüm fikirlerinizi ve görevlerinizi farklı formatlarda dışa aktarın.
          </p>
          
          <div className="export-options">
            <div className="export-card">
              <h5>JSON Format</h5>
              <p>Tam veri yedekleme (Woorkzi'ye geri yüklenebilir)</p>
              <button 
                onClick={() => onExport('json')} 
                className="btn btn-primary"
              >
                JSON İndir
              </button>
            </div>
            
            <div className="export-card">
              <h5>CSV Format</h5>
              <p>Fikir listesi (Excel'de açılabilir)</p>
              <button 
                onClick={() => onExport('csv')} 
                className="btn btn-secondary"
              >
                CSV İndir
              </button>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'import' && (
        <div className="tab-content">
          <h4>Verilerinizi Geri Yükleyin</h4>
          <p className="tab-description">
            Daha önce dışa aktardığınız JSON dosyasını seçin.
          </p>
          
          <div className="import-area">
            <input
              type="file"
              accept=".json"
              onChange={handleFileChange}
              className="file-input"
              id="import-file"
            />
            <label htmlFor="import-file" className="file-label">
              {importFile ? importFile.name : 'JSON dosyası seçin'}
            </label>
            
            {importFile && (
              <div className="import-info">
                <p><strong>Dosya:</strong> {importFile.name}</p>
                <p><strong>Boyut:</strong> {(importFile.size / 1024).toFixed(2)} KB</p>
              </div>
            )}
          </div>

          <div className="modal-actions">
            <button type="button" onClick={handleClose} className="btn btn-secondary">
              İptal
            </button>
            <button 
              onClick={handleImport} 
              disabled={!importFile || importing}
              className="btn btn-primary"
            >
              {importing ? 'Yükleniyor...' : 'Verileri Yükle'}
            </button>
          </div>
        </div>
      )}

      {activeTab === 'stats' && (
        <div className="tab-content">
          <h4>Proje İstatistikleri</h4>
          <div className="stats-grid">
            <div className="stat-box">
              <div className="stat-number">{stats.totalIdeas}</div>
              <div className="stat-label">Toplam Fikir</div>
            </div>
            <div className="stat-box">
              <div className="stat-number">{stats.totalTasks}</div>
              <div className="stat-label">Toplam Görev</div>
            </div>
            <div className="stat-box">
              <div className="stat-number">{stats.completedIdeas}</div>
              <div className="stat-label">Tamamlanan Fikir</div>
            </div>
            <div className="stat-box">
              <div className="stat-number">%{stats.avgProgress}</div>
              <div className="stat-label">Ortalama İlerleme</div>
            </div>
          </div>
        </div>
      )}
    </Modal>
  );
};
